const headerName = ($env.SENDBLUE_WEBHOOK_SECRET_HEADER || 'sb-signing-secret').toLowerCase();
const expected = $env.SENDBLUE_WEBHOOK_SECRET || '';
const headers = $input.first().json.headers || {};
const got = headers[headerName] || headers[headerName.toUpperCase()] || '';
// constant-time-ish comparison
let ok = expected.length > 0 && got.length === expected.length;
if (ok) { let diff = 0; for (let i = 0; i < expected.length; i++) diff |= expected.charCodeAt(i) ^ got.charCodeAt(i); ok = diff === 0; }
return [{ json: { ...$input.first().json, secret_valid: ok } }];

// core-sync: 1.0.0 — mirrors normalizePhone/phoneRef in scripts/lib/agent-core.mjs.
function normalizePhone(raw, defaultCountry = 'US') {
  if (raw === null || raw === undefined) return null;
  const s = String(raw).trim(); if (!s) return null;
  const digits = s.replace(/[^\d+]/g, '');
  if (/^\+\d{8,15}$/.test(digits)) return digits;
  const bare = digits.replace(/\D/g, '');
  if (defaultCountry === 'US') { if (bare.length === 10) return `+1${bare}`; if (bare.length === 11 && bare.startsWith('1')) return `+${bare}`; }
  if (bare.length >= 8 && bare.length <= 15) return `+${bare}`;
  return null;
}
function phoneRef(e164) { if (!e164) return null; let h = 5381; for (let i = 0; i < e164.length; i++) h = ((h << 5) + h + e164.charCodeAt(i)) >>> 0; return `ph_${h.toString(16)}${e164.slice(-2)}`; }
const body = $json.body || $json;
